package com.healthcare.controller;
import com.healthcare.dto.AppointmentDtos.*;import com.healthcare.service.AppointmentService;import jakarta.validation.Valid;import java.security.Principal;import java.util.List;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/appointments") public class AppointmentController {private final AppointmentService service;public AppointmentController(AppointmentService s){service=s;}@PostMapping ResponseEntity<View> book(@Valid @RequestBody Create r,Principal p){return ResponseEntity.status(HttpStatus.CREATED).body(service.book(p.getName(),r));}@GetMapping List<View> mine(Principal p){return service.mine(p.getName());}@PatchMapping("/{id}/cancel") View cancel(@PathVariable Long id,Principal p){return service.cancel(id,p.getName());}}
